&reftitle.description;
public static boolYaf_Registry::has stringname
Comprueba si existe un elemento.

&reftitle.parameters;


  name


    El nombre de la entrada del registro.

  &reftitle.examples;

   Ejemplo de Yaf_Registry::has


<?php
class Bootstrap extends Yaf_Bootstrap_Abstract
{
    public function _initRedis(Yaf_Dispatcher $dispatcher)
    {
        /* se omite el trabajo si una pasada anterior del bootstrap ya lo hizo */
        if (Yaf_Registry::has("redis")) {
            return;
        }

        $config = Yaf_Application::app()->getConfig()->redis;

        $redis = new Redis();
        $redis->connect($config->host, $config->port);

        Yaf_Registry::set("redis", $redis);
    }
}
?>
